import React, { useCallback, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useEffect } from 'react';
import CurtainOverlay from '../components/CurtainOverlay/CurtainOverlay';
import Hero from '../components/Hero/Hero';
import About from '../components/About/About';
import Education from '../components/Education/Education';
import Experience from '../components/Experience/Experience';
import ProjectsCarousel from '../components/Projects/ProjectsCarousel';
import SkillsSection from '../components/Skills/SkillsSection';
import CodeFeature from '../components/CodeFeature/CodeFeature';
import Connect from '../components/Connect/Connect';
import SectionCard from '../components/SectionCard/SectionCard';
import { scrollToId } from '../utils/scrollToSection';

const CARD_COUNT = 6;
const MOBILE_BREAKPOINT = 768;
const CARD_GAP_VH = 0.4; // must match --card-gap: 40dvh in index.css
// --card-sticky-top: calc(12px + 3.5rem + 36px) = 104px at 16px base font
const STICKY_TOP_PX = 104;
const CARD_BOTTOM_INSET_PX = 20; // must match --card-bottom-inset in index.css

export default function Home() {
  const location = useLocation();
  const excessRef = useRef(new Array(CARD_COUNT).fill(0));
  const [totalExcess, setTotalExcess] = useState(0);

  useEffect(() => {
    if (location.state?.scrollTo) {
      const target = location.state.scrollTo;
      requestAnimationFrame(() => scrollToId(target));
      window.history.replaceState({}, '');
    }
  }, [location.state]);

  const handleExcess = useCallback((index, px) => {
    if (excessRef.current[index] === px) return;
    excessRef.current[index] = px;
    if (window.innerWidth < MOBILE_BREAKPOINT) {
      setTotalExcess(excessRef.current.reduce((s, v) => s + v, 0));
    }
  }, []);

  const getCardH = () => window.innerHeight - STICKY_TOP_PX - CARD_BOTTOM_INSET_PX;
  const getGapPx = () => CARD_GAP_VH * window.innerHeight;
  // One full card cycle: card height + spacer gap.
  const getScrollStep = () => getCardH() + getGapPx();

  // Compute per-card scrollStart: index*(cardH + gap) + cumulative excess before this card.
  const getScrollStart = (index) => {
    let cumulative = 0;
    for (let i = 0; i < index; i++) cumulative += excessRef.current[i];
    return index * getScrollStep() + cumulative;
  };

  return (
    <div className="home-page">
      <CurtainOverlay />

      {/*
        --extra-scroll is consumed by the mobile min-height calc in SectionCard.css.
        CSS handles the stickyTop subtraction; we just inject the total excess px.
      */}
      <div
        className="cards-stack"
        style={{ '--total-cards': CARD_COUNT, '--extra-scroll': `${totalExcess}px` }}
      >
        <SectionCard index={0} isLast={false} isWide scrollStart={getScrollStart(0)} scrollStep={getScrollStep()} onExcess={handleExcess}><Hero /></SectionCard>
        <div className="card-spacer" />
        <SectionCard index={1} isLast={false} scrollStart={getScrollStart(1)} scrollStep={getScrollStep()} onExcess={handleExcess}><About /></SectionCard>
        <div className="card-spacer" />
        <SectionCard index={2} isLast={false} scrollStart={getScrollStart(2)} scrollStep={getScrollStep()} onExcess={handleExcess}><Experience /></SectionCard>
        <div className="card-spacer" />
        <SectionCard index={3} isLast={false} scrollStart={getScrollStart(3)} scrollStep={getScrollStep()} onExcess={handleExcess}><Education /></SectionCard>
        <div className="card-spacer" />
        <SectionCard index={4} isLast={false} isWide scrollStart={getScrollStart(4)} scrollStep={getScrollStep()} onExcess={handleExcess}><ProjectsCarousel /></SectionCard>
        <div className="card-spacer" />
        <SectionCard index={5} isLast={true} scrollStart={getScrollStart(5)} scrollStep={getScrollStep()} onExcess={handleExcess}><SkillsSection /></SectionCard>
      </div>

      <div className="floor-rail">
        <CodeFeature />
        <Connect />
      </div>
    </div>
  );
}
