// src/components/CurtainOverlay/CurtainOverlay.js
import React, { useEffect, useRef } from 'react';
import curtainImg from '../../assets/curtain.png';
import revealImg from '../../assets/dvir-reveal.png';
import { useLenisRef } from '../../context/ScrollContext';
import './CurtainOverlay.css';

const STAGE_COUNT = 4;   // stages 0-3: "3","2","1", image
const SLIDE_STAGES = 1;  // stage 4: curtain slides up
const TOTAL_STAGES = STAGE_COUNT + SLIDE_STAGES;
const STAGE_SIZE = 320;  // px of accumulated delta per stage

// SVG arc path for the clockwise sweep sector starting at 12 o'clock
function sweepPath(deg) {
  if (deg <= 0) return '';
  if (deg >= 359.99) {
    // Full circle: two half-arcs
    return 'M 100,100 L 100,7 A 93,93 0 1,1 99.999,7 Z';
  }
  const rad = (deg * Math.PI) / 180;
  const ex = 100 + 93 * Math.sin(rad);
  const ey = 100 - 93 * Math.cos(rad);
  const large = deg > 180 ? 1 : 0;
  return `M 100,100 L 100,7 A 93,93 0 ${large},1 ${ex.toFixed(3)},${ey.toFixed(3)} Z`;
}

function buildTicks() {
  return Array.from({ length: 12 }, (_, i) => {
    const angle = (i * 30 - 90) * Math.PI / 180;
    const isMajor = i % 3 === 0;
    const r1 = isMajor ? 80 : 86;
    const x1 = (100 + r1 * Math.cos(angle)).toFixed(3);
    const y1 = (100 + r1 * Math.sin(angle)).toFixed(3);
    const x2 = (100 + 93 * Math.cos(angle)).toFixed(3);
    const y2 = (100 + 93 * Math.sin(angle)).toFixed(3);
    return (
      <line
        key={i}
        x1={x1} y1={y1} x2={x2} y2={y2}
        stroke={isMajor ? 'rgba(255,228,130,0.9)' : 'rgba(255,228,130,0.5)'}
        strokeWidth={isMajor ? '2.5' : '1.2'}
        strokeLinecap="round"
      />
    );
  });
}

const TICKS = buildTicks();

export default function CurtainOverlay() {
  const lenisRef = useLenisRef();
  const curtainRef = useRef(null);
  const filmFrameRef = useRef(null);
  const sweepRef = useRef(null);
  const numberRef = useRef(null);
  const imageContainerRef = useRef(null);
  const flashRef = useRef(null);
  const scrollHintRef = useRef(null);

  useEffect(() => {
    document.documentElement.style.overflow = '';
    document.body.style.overflow = '';

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    window.scrollTo(0, 0);

    const curtainEl = curtainRef.current;
    const filmEl = filmFrameRef.current;
    const sweepEl = sweepRef.current;
    const numEl = numberRef.current;
    const imgEl = imageContainerRef.current;
    const flashEl = flashRef.current;
    const hintEl = scrollHintRef.current;

    const threshold = STAGE_SIZE * TOTAL_STAGES;
    let phase = 'curtain';
    let virtualY = 0;
    let rafId = null;
    let prevStage = -1;

    const lock = () => {
      document.documentElement.style.overflow = 'hidden';
      document.body.style.overflow = 'hidden';
      lenisRef.current?.stop();
    };
    const unlock = () => {
      document.documentElement.style.overflow = '';
      document.body.style.overflow = '';
      // Reset Lenis to scroll=0 before re-enabling so accumulated wheel
      // deltas from the curtain phase don't jump the page.
      lenisRef.current?.scrollTo(0, { immediate: true });
      lenisRef.current?.start();
    };

    lock();

    const applyProgress = () => {
      const rawStage = virtualY / STAGE_SIZE;
      const stage = Math.min(Math.floor(rawStage), TOTAL_STAGES - 1);
      const stageProgress = rawStage - Math.floor(rawStage);
      const goingForward = stage > prevStage;

      if (hintEl) {
        hintEl.style.opacity = virtualY > STAGE_SIZE * 0.3 ? '0' : '1';
      }

      if (stage < STAGE_COUNT) {
        curtainEl.style.transform = 'translateY(0%)';

        if (stage < 3) {
          // Drive sweep directly from scroll — this IS the scroll-scrubbed animation
          sweepEl.setAttribute('d', sweepPath(stageProgress * 360));

          if (stage !== prevStage) {
            filmEl.style.opacity = '1';
            filmEl.style.transition = 'opacity 0.15s ease';
            imgEl.style.transition = 'none';
            imgEl.style.opacity = '0';

            numEl.textContent = (3 - stage).toString();

            if (goingForward && prevStage >= 0) {
              numEl.classList.remove('curtain-number--flash');
              void numEl.offsetWidth;
              numEl.classList.add('curtain-number--flash');
            } else {
              numEl.classList.remove('curtain-number--flash');
            }

            prevStage = stage;
          }
        } else {
          // Stage 3: image reveal
          sweepEl.setAttribute('d', '');

          if (stage !== prevStage) {
            if (goingForward) {
              filmEl.style.transition = 'opacity 0.2s ease';
              filmEl.style.opacity = '0';
              flashEl.classList.remove('curtain-flash--active');
              void flashEl.offsetWidth;
              flashEl.classList.add('curtain-flash--active');
              imgEl.style.transition = 'none';
              imgEl.style.opacity = '0';
              imgEl.style.transform = 'scale(0.85)';
              setTimeout(() => {
                imgEl.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
                imgEl.style.opacity = '1';
                imgEl.style.transform = 'scale(1)';
              }, 120);
            } else {
              filmEl.style.transition = 'opacity 0.2s ease';
              filmEl.style.opacity = '0';
              imgEl.style.transition = 'opacity 0.3s ease';
              imgEl.style.opacity = '1';
              imgEl.style.transform = 'scale(1)';
            }
            prevStage = stage;
          }
        }

      } else {
        // Stage 4: slide curtain up
        const slideProgress = Math.min((virtualY - STAGE_COUNT * STAGE_SIZE) / STAGE_SIZE, 1);
        curtainEl.style.transform = `translateY(${-slideProgress * 100}%)`;

        if (prevStage !== TOTAL_STAGES - 1) {
          filmEl.style.opacity = '0';
          imgEl.style.opacity = '1';
          imgEl.style.transform = 'scale(1)';
          prevStage = TOTAL_STAGES - 1;
        }

        if (slideProgress >= 1) {
          unlock();
          window.scrollTo(0, 0);
          phase = 'page';
        }
      }
    };

    const handleDelta = (delta) => {
      if (phase === 'curtain') {
        virtualY = Math.max(0, virtualY + delta);
        if (!rafId) rafId = requestAnimationFrame(() => {
          rafId = null;
          applyProgress();
        });
      } else {
        if (window.scrollY <= 0 && delta < 0) {
          lock();
          phase = 'curtain';
          prevStage = TOTAL_STAGES;
          virtualY = Math.max(0, threshold + delta);
          if (!rafId) rafId = requestAnimationFrame(() => {
            rafId = null;
            applyProgress();
          });
        }
      }
    };

    const onWheel = (e) => {
      if (document.body.classList.contains('drawer-open')) return;
      if (phase === 'curtain' || (phase === 'page' && window.scrollY <= 0 && e.deltaY < 0)) {
        e.preventDefault();
      }
      handleDelta(e.deltaY);
    };

    let touchStartY = 0;
    const onTouchStart = (e) => { touchStartY = e.touches[0].clientY; };
    const onTouchMove = (e) => {
      if (document.body.classList.contains('drawer-open')) return;
      const delta = touchStartY - e.touches[0].clientY;
      touchStartY = e.touches[0].clientY;
      if (phase === 'curtain' || (phase === 'page' && window.scrollY <= 0 && delta < 0)) {
        e.preventDefault();
      }
      handleDelta(delta);
    };

    window.addEventListener('wheel', onWheel, { passive: false });
    window.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: false });

    return () => {
      window.removeEventListener('wheel', onWheel);
      window.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      if (rafId) cancelAnimationFrame(rafId);
      unlock();
    };
  }, [lenisRef]);

  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return null;

  return (
    <div
      ref={curtainRef}
      className="curtain-overlay"
      style={{ backgroundImage: `url(${curtainImg})` }}
      aria-hidden="true"
    >
      {/* Orbiting spotlights */}
      <div className="curtain-orbit curtain-orbit-1"><div className="curtain-spot" /></div>
      <div className="curtain-orbit curtain-orbit-2"><div className="curtain-spot" /></div>
      <div className="curtain-orbit curtain-orbit-3"><div className="curtain-spot" /></div>
      <div className="curtain-orbit curtain-orbit-4"><div className="curtain-spot" /></div>
      <div className="curtain-orbit curtain-orbit-5"><div className="curtain-spot" /></div>
      <div className="curtain-orbit curtain-orbit-6"><div className="curtain-spot" /></div>
      <div className="curtain-orbit curtain-orbit-7"><div className="curtain-spot" /></div>

      {/* Film leader countdown */}
      <div ref={filmFrameRef} className="curtain-film-frame">
        <div className="curtain-film-svg-wrap">
          <svg
            className="curtain-film-svg"
            viewBox="0 0 200 200"
            xmlns="http://www.w3.org/2000/svg"
          >
            {/* Gray base fill inside the circle */}
            <circle cx="100" cy="100" r="93" fill="rgba(155, 140, 110, 0.22)" />

            {/* Clockwise sweep sector — d updated by JS */}
            <path ref={sweepRef} fill="rgba(4, 6, 16, 0.82)" d="" />

            {/* Outer ring */}
            <circle cx="100" cy="100" r="93" fill="none" stroke="rgba(255,228,130,0.7)" strokeWidth="1.5" />
            {/* Inner ring */}
            <circle cx="100" cy="100" r="70" fill="none" stroke="rgba(255,228,130,0.25)" strokeWidth="0.8" />

            {/* Crosshairs spanning full frame */}
            <line x1="0" y1="100" x2="200" y2="100" stroke="rgba(255,228,130,0.38)" strokeWidth="0.8" />
            <line x1="100" y1="0" x2="100" y2="200" stroke="rgba(255,228,130,0.38)" strokeWidth="0.8" />

            {/* Tick marks on outer ring */}
            {TICKS}

            {/* Corner brackets */}
            <path d="M 2,14 L 2,2 L 14,2"   fill="none" stroke="rgba(255,228,130,0.6)" strokeWidth="1.5" strokeLinecap="square" />
            <path d="M 186,2 L 198,2 L 198,14" fill="none" stroke="rgba(255,228,130,0.6)" strokeWidth="1.5" strokeLinecap="square" />
            <path d="M 2,186 L 2,198 L 14,198" fill="none" stroke="rgba(255,228,130,0.6)" strokeWidth="1.5" strokeLinecap="square" />
            <path d="M 198,186 L 198,198 L 186,198" fill="none" stroke="rgba(255,228,130,0.6)" strokeWidth="1.5" strokeLinecap="square" />
          </svg>

          <span ref={numberRef} className="curtain-number">3</span>
        </div>
      </div>

      {/* Dvir reveal image */}
      <div ref={imageContainerRef} className="curtain-image-reveal" style={{ opacity: 0, transform: 'scale(0.85)' }}>
        <img src={revealImg} alt="" className="curtain-reveal-img" />
      </div>

      {/* Flash */}
      <div ref={flashRef} className="curtain-flash" />

      {/* Scroll hint */}
      <div ref={scrollHintRef} className="curtain-scroll-hint">
        <span>SCROLL</span>
        <div className="curtain-scroll-arrow" />
      </div>
    </div>
  );
}
